from lib import *
S = SS('q8')
steps = [
    step("prefetch=5、队列里 20 条,消费者收到就不 ack:收到 5 条,(ready, unacked) = (15, 5)。ack 第 1 条之后又收到 1 条(共 6),(ready, unacked) = (14, 5)——未确认的数量始终顶在 5;再 ack 到最后一条(multiple=True)后共收到 11 条,仍是 5 个 unacked。prefetch 限制的是“已投递但未确认”的条数,不是总条数。rabbitmqctl list_channels 能看到这个 channel 的 prefetch_count = 5、messages_unacknowledged = 5、consumer_count = 1。", t=tl(S(1)), mark=lidx(S(1), '(15, 5)', '(14, 5)', '(9, 5)'), done=lidx(S(1), '5\t5\t1', '消费者收到了 5 条'), b=bars([['收到、未 ack', 5, 'unacked 5'], ['ack 1 条后', 5, 'unacked 5'], ['ack 到最后一条后', 5, 'unacked 5']], 5, mark=[0, 1, 2]), kv=KV([['prefetch', '已投递未确认的上限'], ['ack 一条', '放出一条新的'], ['multiple=True', '一次放出多条']], ['prefetch'])),
    step("一个 channel 上两个消费者(a、b),basic.qos(prefetch=5):global=False 时每个消费者各 5 条,合计 10,(ready, unacked) = (30, 10);global=True 在 4.3.6 默认配置下也得到 a=5、b=5,没有报错——因为 global_qos 在 4.3.6 里是 denied_by_default 的废弃特性,请求被当成每消费者限制处理(日志里记了一条 error)。显式在配置里打开 deprecated_features.permit.global_qos 后,global=True 才变成整个 channel 共享 5:a=5、b=0,合计 5,(ready, unacked) = (35, 5)。", t=tl(S(2)), mark=lidx(S(2), '打开 permit.global_qos', '默认配置 global=True'), done=lidx(S(2), '默认配置 global=False', 'list_deprecated_features', '默认配置下 global=True 没有报错'), b=bars([['global=False', 10, '合计 10'], ['global=True(默认配置)', 10, '合计 10'], ['global=True(放开)', 5, '合计 5']], 10, mark=[2], done=[0, 1]), kv=KV([['global=False', '每个消费者各自 5'], ['global=True 默认配置', '被当成每消费者,不报错'], ['放开 permit.global_qos', '整个 channel 共享 5']], ['global=True 默认配置'])),
    step("自动确认(no_ack)的消费者不受 prefetch 限制:设了 prefetch=5 但 auto_ack=True,1000 条被一口气全推完,收到 1000 条,(ready, unacked) = (0, 0)——没有“未确认”,自然也没有可限制的东西。所以用了自动确认就别指望靠 prefetch 做背压。", t=tl(S(3)), mark=lidx(S(3), 'auto_ack=True'), done=lidx(S(3), 'auto_ack=True'), kv=KV([['auto_ack=True', 'prefetch 不起作用'], ['结果', '1000 条一次推完'], ['背压', '需要手动 ack']], ['auto_ack=True'])),
    step("loopback 上(几乎没有延迟),20000 条 100 字节的消息、每条处理完立刻 ack:prefetch=1 要 2058 ms(9718 条/秒),10 是 674 ms(29665 条/秒),100 是 635 ms,1000 是 576 ms,0(无限)是 527 ms(37944 条/秒)。prefetch=1 慢是因为每条都要“ack → 等下一条”一次往返;提到 10 就拿到了绝大部分吞吐,再往上收益很小。", t=tl(S(4)), mark=lidx(S(4), '1   ', '10  '), done=lidx(S(4), '100  ', '1000 ', '0(无限)'), b=bars([['prefetch 1', 9718, '9718 条/秒'], ['prefetch 10', 29665, '29665 条/秒'], ['prefetch 100', 31520, '31520 条/秒'], ['prefetch 1000', 34711, '34711 条/秒'], ['prefetch 0', 37944, '37944 条/秒']], 37944, mark=[0], done=[1, 2, 3, 4]), kv=KV([['prefetch=1', '9718 条/秒'], ['prefetch=10', '29665 条/秒'], ['prefetch=1000', '34711 条/秒']], ['prefetch=1'])),
    step("经过代理给每个方向加 5 ms(往返约 10 ms),消费 2000 条:prefetch=1 要 25706 ms(78 条/秒),10 是 2639 ms(758 条/秒),100 是 258 ms(7761 条/秒),1000 是 148 ms(13488 条/秒)。前几行吞吐几乎等于 prefetch ÷ 往返时间(100、1000、10000 条/秒的理论上限):窗口 = prefetch 条,每个往返最多流过一个窗口。跨机房或跨区的消费者如果还用 prefetch=1,吞吐就被往返延迟锁死了。", t=tl(S(5)), mark=lidx(S(5), '1     ', '10    '), done=lidx(S(5), '100   ', '1000  '), b=bars([['prefetch 1', 78, '78 条/秒'], ['prefetch 10', 758, '758 条/秒'], ['prefetch 100', 7761, '7761 条/秒'], ['prefetch 1000', 13488, '13488 条/秒']], 13488, mark=[0, 1], done=[2, 3]), kv=KV([['往返 10 ms', 'prefetch=1 → 约 100 条/秒上限'], ['实测', '78 / 758 / 7761 条/秒'], ['窗口', 'prefetch ÷ 往返时间']], ['窗口'])),
    step("prefetch 太大的代价:prefetch=1000、队列 5000 条,消费者收到后不 ack 就断开。在线时 (ready, unacked) = (4000, 1000);断开之后变成 (5000, 0)——那 1000 条回到队列。把 5000 条全取出来,redelivered=True 的正好 1000 条,就是被推给那个崩溃消费者的那批。prefetch 越大,单个消费者持有的在途消息越多:崩溃时重投越多,别的消费者也分不到这些消息(下一篇讲公平分发)。", t=tl(S(6)), mark=lidx(S(6), '(5000, 0)', 'redelivered=True 的有 1000'), done=lidx(S(6), '消费者在线时'), b=bars([['在线: ready', 4000, '4000'], ['在线: unacked', 1000, '1000'], ['断开后: ready', 5000, '5000'], ['断开后: redelivered', 1000, '1000']], 5000, mark=[3], done=[0, 1, 2]), kv=KV([['prefetch=1000', '崩溃时最多 1000 条重投'], ['在途消息', '别的消费者拿不到'], ['选值', '吞吐和重投成本折中']], ['prefetch=1000'])),
]
A = mkartq('q8', 8, 'RabbitMQ,prefetch,basic.qos,吞吐,背压,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测 prefetch:它限制的是已投递未确认的条数;global_qos 在 4.3.6 默认被当成每消费者限制;自动确认不受限;loopback 上 prefetch=1 是 9718 条/秒、10 是 29665 条/秒;往返 10 ms 时 prefetch=1 只有 78 条/秒、1000 是 13488 条/秒;prefetch=1000 的消费者崩溃会让 1000 条重投。',
    'prefetch 到底限制什么?global 标志有什么用?太小和太大各会怎样?这篇先数 ready / unacked 看清含义,再在 loopback 和加了 10 ms 往返的链路上分别量吞吐,最后看消费者崩溃时的代价。',
    [('9718 → 29665 条/秒', 'loopback 上 prefetch 从 1 提到 10 的消费吞吐'), ('78 条/秒', '往返 10 ms 时 prefetch=1 的消费吞吐,约等于 1 ÷ 往返时间'), ('1000 条', 'prefetch=1000 的消费者崩溃后重新入队的消息数(redelivered=True)')],
    [('含义', '<p><code>basic.qos(prefetch_count=N)</code> 让 broker 给每个消费者最多推 N 条未确认的消息;每确认一条才再推一条。它限制的是在途(unacked)数,不是总数。</p>'),
     ('global 标志', '<p>AMQP 里 <code>global=True</code> 本来表示整个 channel 共享这个限制。4.3.6 把 <code>global_qos</code> 列为 denied_by_default 的废弃特性:默认配置下请求不报错,但效果和 global=False 一样(每消费者各 N);显式打开 <code>deprecated_features.permit.global_qos</code> 才共享。</p>'),
     ('自动确认', '<p>auto_ack 的消费者没有未确认状态,prefetch 对它不起作用,1000 条一次推完。</p>'),
     ('loopback 上的吞吐', '<p>prefetch=1 因为每条一次往返只有 9718 条/秒,提到 10 后 29665 条/秒,再提到 1000 也只有 34711 条/秒,收益递减。</p>'),
     ('有延迟的链路', '<p>往返变成 10 ms 之后差距是量级的:吞吐 ≈ prefetch ÷ 往返时间(实测 78、758、7761、13488 条/秒)。跨机房的消费者不能用 prefetch=1。</p>'),
     ('代价', '<p>prefetch 越大,一个消费者攥着的在途消息越多:它崩溃时这些消息全部重投,慢的消费者还会把消息“囤”在手里不让别人处理。</p>')],
    steps,
    [ENV_Q + '。第四节 loopback 每个 prefetch 值 3 次取中位数;第五节经过自己写的代理,每个方向加 5 ms 延迟(排队后按期限发送,保持流水线),每个值只测 1 次(prefetch=1 要 25 秒);消费者每条处理完立刻 ack,处理本身为零耗时',
     '没有验证:消费者处理耗时不为零时 prefetch 与吞吐的关系(第 9 篇会涉及);quorum 队列和 stream 上的 prefetch;多消费者共享队列时的 prefetch 分布;global_qos 放开后与 quorum 队列的交互;消息体更大时的 prefetch 内存占用;客户端库自己缓冲带来的差异(pika 的 BlockingConnection 回调模式)'],
    'prefetch')
